package com.opensocket.aievent.core.a2a.application.service;
import com.opensocket.aievent.core.a2a.*;
import com.opensocket.aievent.core.a2a.application.port.in.A2ALateResultGovernanceUseCase;
import java.time.OffsetDateTime; import java.time.ZoneOffset; import java.util.List; import org.springframework.transaction.annotation.Transactional;
public class A2ALateResultGovernanceService implements A2ALateResultGovernanceUseCase { private final A2AResultQuarantineRepository repo; public A2ALateResultGovernanceService(A2AResultQuarantineRepository r){repo=r;} @Transactional(readOnly=true) public List<A2AResultQuarantine> open(String t,int l){return repo.findOpen(t,Math.max(1,Math.min(l,1000)));} @Transactional public A2AResultQuarantine resolve(String t,String id,A2ALateResultResolution d,String actor,String reason){A2AResultQuarantine q=repo.findById(t,id).orElseThrow(()->new IllegalArgumentException("A2A Result Quarantine not found: "+id));if(!"OPEN".equals(q.getStatus()))return q;String target=d==A2ALateResultResolution.ACCEPT_AS_GOVERNANCE_EVIDENCE?"RESOLVED_ACCEPTED":"RESOLVED_REJECTED";OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);if(!repo.resolveExpectedStatus(t,id,"OPEN",target,actor,reason,now))throw new IllegalStateException("A2A_QUARANTINE_RESOLUTION_CONFLICT");return repo.findById(t,id).orElseThrow();} }
